package com.logatron.processor;
import com.fasterxml.jackson.databind.ObjectMapper;import com.logatron.contracts.ingestion.ParserProfile;import com.logatron.processor.parse.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class ParserAndNormalizationTest {@Test void parsesJsonAliasesUnicodeAndIdentifiers(){var p=new JsonLogParser(new ObjectMapper(),new TimestampNormalizer());var e=p.parse(TestFixtures.raw(ParserProfile.JSON,"{\"@timestamp\":\"2026-08-27T10:30:01.125Z\",\"severity\":\"ERROR\",\"message\":\"नमस्ते\",\"trace_id\":\"abc\",\"orderToken\":\"demo-order-42\"}"));assertThat(e.timestamp()).isEqualTo(Instant.parse("2026-08-27T10:30:01.125Z"));assertThat(e.message()).isEqualTo("नमस्ते");assertThat(e.traceId()).isEqualTo("abc");assertThat(e.orderToken()).isEqualTo("demo-order-42");}
 @Test void parsesPlaintextMultilineAsOneEvent(){String line="2026-08-27 10:30:01.125 ERROR [worker-1] com.example.Service - Failed requestId=req-1\njava.sql.SQLTimeoutException: timeout\n    at com.example.Service.run(Service.java:1)";var e=new PlaintextLogParser(new TimestampNormalizer()).parse(TestFixtures.raw(ParserProfile.PLAINTEXT,line));assertThat(e.message()).contains("Failed");assertThat(e.requestId()).isEqualTo("req-1");assertThat(e.exceptionType()).isEqualTo("java.sql.SQLTimeoutException");assertThat(e.stackTrace()).contains("Service.java:1");}
 @Test void malformedJsonFailsExplicitly(){assertThatThrownBy(()->new JsonLogParser(new ObjectMapper(),new TimestampNormalizer()).parse(TestFixtures.raw(ParserProfile.JSON,"{bad"))).isInstanceOf(ProcessingException.class).hasMessageContaining("cannot be parsed");}
 @Test void invalidTimestampIsNotSilentlyReplaced(){assertThatThrownBy(()->new TimestampNormalizer().parse("not-time")).isInstanceOf(ProcessingException.class);}
 @Test void severityAliasesNormalize(){var s=new SeverityNormalizer();assertThat(s.normalize("WARNING")).isEqualTo("WARN");assertThat(s.normalize("ERR")).isEqualTo("ERROR");assertThat(s.normalize("CRITICAL")).isEqualTo("FATAL");assertThat(s.normalize("odd")).isEqualTo("UNKNOWN");}}